<section <?php echo nextsaas_section_attrs( 'home-workflow', $attributes, array( 'section', 'work-section' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?>><div class="container"><div class="hero-split"><div><p class="eyebrow" data-nextsaas-rich="eyebrow"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'eyebrow' ) ); ?></p><h2 data-nextsaas-rich="heading"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'heading' ) ); ?></h2><p class="lead" data-nextsaas-rich="lead"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'lead' ) ); ?></p></div><figure style="margin:0"><img class="content-img" src="<?php echo esc_url( nextsaas_attr( $attributes, 'mediaUrl' ) ); ?>" width="1400" height="935" alt="<?php echo esc_attr( nextsaas_attr( $attributes, 'mediaAlt' ) ); ?>" loading="lazy"><figcaption class="photo-note"><span data-nextsaas-rich="photoLabel"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'photoLabel' ) ); ?></span><span data-nextsaas-rich="photoCredit"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'photoCredit' ) ); ?></span></figcaption></figure></div><div class="work-steps"><?php foreach ( $nextsaas_steps as $nextsaas_i => $nextsaas_step ) : ?><article class="work-step"><span class="num" data-nextsaas-rich="steps.<?php echo esc_attr( (string) $nextsaas_i ); ?>.meta"><?php echo nextsaas_rich( (string) ( $nextsaas_step['meta'] ?? '' ) ); ?></span><h3 data-nextsaas-rich="steps.<?php echo esc_attr( (string) $nextsaas_i ); ?>.heading"><?php echo nextsaas_rich( (string) ( $nextsaas_step['heading'] ?? '' ) ); ?></h3><p data-nextsaas-rich="steps.<?php echo esc_attr( (string) $nextsaas_i ); ?>.body"><?php echo nextsaas_rich( (string) ( $nextsaas_step['body'] ?? '' ) ); ?></p></article><?php endforeach; ?></div></div></section>
